function progDocBody_(body, title, sub, days, notes, extra) { body.clear(); docInit_(body);
  // פורמט קבוע (20.10.26): כותרת עם שם+תאריך+מטרה+מספר אימונים, שורת "פיצול:", אימון = כותרת + טבלה של 5 עמודות עם כותרת כהה
  docPara_(body, title, { h: DocumentApp.ParagraphHeading.HEADING1, bold: true, size: 20, color: DOC_.accent, after: 4 });
  if (sub) { const sm = String(sub).match(/^(פיצול: )(.*)$/); if (sm) docLbl_(body, sm[1], sm[2], { after: 6 }); else docPara_(body, sub, { size: 10.5, color: DOC_.grey, after: 8 }); }
  if (notes) docLbl_(body, 'הערות אישיות: ', String(notes).slice(0, 1500), { size: 10.5, after: 4 });
  (extra || []).forEach(x => docLbl_(body, '', x, { size: 10.5, after: 2 }));
  (days || []).forEach((d, i) => { const ex = (d.exercises || d.ex || []).filter(e => String(e.n || '').trim()); if (!ex.length) return;
    docH2_(body, 'אימון ' + (i + 1) + ' – ' + String(d.lbl || '').slice(0, 80));
    docPara_(body, 'חימום: 10 דקות הליכה לאחור או אופניים, ואז סט חימום קל בתרגיל הראשון.', { size: 10, color: DOC_.grey, after: 4 });
    const rows = ex.map(e => { let sets = String(e.s == null ? '' : e.s); const sm = sets.match(/^(\d+)\((.+)\)$/); if (sm) sets = sm[1] + ' (+' + sm[2].replace('ח', ' חימום') + ')';
      return [/Adduction|סגירת רגליים/.test(e.n) ? 'מקרבי ירך' : (PG_.MN[e.mu] || e.mu || ''), String(e.n || '').trim() + (e.note ? String.fromCharCode(10) + String(e.note).trim() : ''), sets, String(e.r == null ? '' : e.r).replace(/[–—]/g, '-'), String(e.rest == null ? '' : e.rest)]; });
    docTable_(body, ['קבוצת שריר', 'תרגיל', 'סטים', 'חזרות', 'מנוחה (דק׳)'], rows, [80, 238, 46, 68, 72], { center: [2, 3, 4], zebra: true, boldCols: [1], darkHead: true });
    docPara_(body, '', { after: 2 }); });
  docPara_(body, 'עולים במשקל כשמגיעים לחזרות המקסימליות בכל הסטים. משהו כואב או לא ברור – שולחים לי סרטון.', { italic: true, size: 10.5, color: DOC_.grey, before: 10 }); docRtlAll_(body); }
